import React, { Component } from 'react';

import './App.css';

import Header from './Header'
import Footer from './Footer'
import DraftBoard from './DraftBoard'
import DraftBoard2 from './DraftBoard2'

class App extends Component {
  constructor() {
      super();

      this.state = {
          rankSource: 'sportsbooks'
      };
    }

  render() {
    return (
      <div id="main" className="container-fluid clear-top">
        <Header />
        <div className="form-group col-md-12 row">
          <select value={ this.state.rankSource } onChange={(e) => this.setState({rankSource: e.target.value}) } >
            <option value="sportsbooks">intersecting_lines</option>
            <option value="borischen">Boris Chen</option>
          </select>
        </div>
        <div className='row'>
          {this.state.rankSource == 'borischen' ? <DraftBoard /> : <DraftBoard2 /> }
        </div>
      </div>
    );
  }
}

export default App;
