import React, { PureComponent } from 'react';

import PropTypes from 'prop-types';


class PlayerTable2 extends PureComponent {
  rows() {
    let players = this.props.players.slice();

    if (this.props.size) {
      players = players.slice(0, this.props.size);
    }

    return players.map((player, i) => {
      return (
        <tr key={i}
            className={this.trClassName(player.tier, this.props.disableColor)}
            onClick={() => this.onClick(player)}>
          <td key={1}>{player['drafted']}</td>
          <td key={2}>{player['Player']}</td>
          <td key={3}>{player['Position']}</td>
          <td key={4}>{player['team_abbrev']}</td>
          <td key={5}>BYE {player['bye_week']}</td>
        </tr>
      )
    });
  }

  onClick(player) {
    if (this.props.onClick) {
      return this.props.onClick(player);
    }
  }

  trClassName(tier, disable) {
    if (disable) {
      return 'pointer'
    }
    if (tier % 4 === 0) {
      return 'active pointer'
    }
    if (tier % 4 === 1) {
      return 'success pointer'
    }
    if (tier % 4 === 2) {
      return 'warning pointer'
    }
    if (tier % 4 === 3) {
      return 'info pointer'
    }
    return 'danger pointer'
  }

  render() {
    return (
      <table className='table table-condensed table-hover table-striped'>
        <tbody>{this.rows()}</tbody>
      </table>
    );
  }
}

PlayerTable2.propTypes = {
  players: PropTypes.array.isRequired,
  fields: PropTypes.array.isRequired,

  onClick: PropTypes.func,
  size: PropTypes.number,
  disableColor: PropTypes.bool,
};

export default PlayerTable2
