import React, { Component } from 'react';

import UndraftedAll from './UndraftedAll'
import UndraftedPositions from './UndraftedPositions'
import Drafted2 from './Drafted2'

import jQuery from 'jquery';
import DataTable from 'datatables.net-react';
import 'datatables.net-buttons-dt';
import 'datatables.net-buttons/js/buttons.colVis.mjs';
import 'datatables.net-fixedcolumns-dt';
import 'datatables.net-fixedheader-dt';
import 'datatables.net-rowreorder-dt';
import 'datatables.net-colreorder-dt';

import 'bootstrap/dist/css/bootstrap.min.css';
import 'datatables.net-bs5';

// DataTables Bootstrap 5 CSS
import 'datatables.net-bs5/css/dataTables.bootstrap5.min.css';

 
// DataTable.use(DT);

window.$ = jQuery; // make $ global
window.jQuery = jQuery; // sometimes required by DataTables

class DraftBoard extends Component {
    constructor() {
      super();

      this.state = {
        players: [],
        filteredPlayers: [],
        positions: ['All'],
        selectedPositions: ['All'],
        filterByRookie: false,
        isLoading: false,
        currentDraftPick: 0,
        fetchError: null,
        format: 'bn_league',
        query: '',
      };

      this.tableRef = React.createRef();
    }

    componentDidMount() {
      const savedState = localStorage.getItem('draftBoardState');
      if (!savedState) {
        // No saved state, so load players anew
        this.fetchPlayers(this.state.format);
        return;
      }
      try {
        const parsed = JSON.parse(savedState);
        // Merge saved keys into initial state
        this.setState(prev => ({
          ...prev,
          players: parsed.players || [],
          filteredPlayers: parsed.filteredPlayers || [],
          positions: parsed.positions || ['All'],
          currentDraftPick: parsed.currentDraftPick || 0,
          format: parsed.format || 'bn_league',
        }), () => {
          this.initDataTable();
        });
      } catch (err) {
        console.error('Error parsing saved state:', err);
      }
    }

    componentDidUpdate(prevProps, prevState) {
      // Save updates to local storage if state has changed
      if (
        this.state.players !== prevState.players ||
        this.state.filteredPlayers !== prevState.filteredPlayers ||
        this.state.positions !== prevState.positions ||
        this.state.currentDraftPick !== prevState.currentDraftPick ||
        this.state.format !== prevState.format
      ) {
        const { players, filteredPlayers, positions, currentDraftPick, format } = this.state;
        localStorage.setItem(
          'draftBoardState',
          JSON.stringify({ players, filteredPlayers, positions, currentDraftPick, format })
        );
      }
    }

    initDataTable() {
      let all_keys = Object.keys(this.state.players[0]);

      let columns = [
        { title: 'Team Name', data: 'Team Name', visible: false },
        { title: 'Player', data: 'Player', className: 'player-col' },
        { title: 'Position', data: 'Position' },
        { title: 'Team', data: 'team_abbrev' },
        { title: 'Bye Week', data: 'bye_week' },
        { title: 'Total Points', data: 'Total Points' },
        {
          title: 'Diff to Next',
          data: null,  // data is computed
          render: (data, type, row, meta) => {
            if (row['Total Points'] === null)
              return null;
            const playersAtPosition = this.state.players
              .filter(p => p.Position === row.Position && !p.drafted && p.Player !== row.Player)
              .sort((a,b) => b['Total Points'] - a['Total Points']);
            const next = playersAtPosition[0];
            if (next['Total Points'] === null)
              return null;
            return (row['Total Points'] - next['Total Points']).toFixed(1);
          }
        },
        {
          title: 'Diff to Next5',
          data: null,  // data is computed
          render: (data, type, row, meta) => {
            if (row['Total Points'] === null)
              return null;
            const playersAtPosition = this.state.players
              .filter(p => p.Position === row.Position && !p.drafted && p.Player !== row.Player)
              .sort((a,b) => b['Total Points'] - a['Total Points']);
            const next5 = playersAtPosition.slice(0, 5).filter((p) => p['Total Points'] !== null);;
            // Check array exists
            if (next5 === undefined || next5.length == 0)
              return null;
            // Divide by length in case it's less than 5
            return (row['Total Points'] - next5.reduce((sum, p) => (p['Total Points'] + sum), 0)/next5.length).toFixed(1);
          }
        },
        {
          title: 'Diff to Next13',
          data: null,  // data is computed
          render: (data, type, row, meta) => {
            if (row['Total Points'] === null)
              return null;
            const playersAtPosition = this.state.players
              .filter(p => p.Position === row.Position && !p.drafted && p.Player !== row.Player)
              .sort((a,b) => b['Total Points'] - a['Total Points']);
            const next13 = playersAtPosition.slice(0, 13).filter((p) => p['Total Points'] !== null);
            // Check array exists
            if (next13 === undefined || next13.length == 0)
              return null;
            // Divide by length in case it's less than 13
            return (row['Total Points'] - next13.reduce((sum, p) => (p['Total Points'] + sum), 0)/next13.length).toFixed(1);
          }
        },
        { title: 'Age', data: 'age' },
        {
          title: 'Rookie', data: 'is_rookie',
          render: (data, type, row, meta) => (data === true ? '✅' : '')
        },
        { title: 'BC Tier', data: 'bc_tier' },
        { title: 'BC Rank', data: 'bc_rank' },
        { title: 'BC Dev', data: 'bc_std_dev' },
        // Include these if they are present. God this looks dumb, I wish there were a better way to do this ...
        ... all_keys.includes('week_17') ? [{ title: 'Wk 17 Opp', data: 'week_17' }] : [],
        ... all_keys.includes('week_16') ? [{ title: 'Wk 16 Opp', data: 'week_16' }] : [],
        ... all_keys.includes('week_15') ? [{ title: 'Wk 15 Opp', data: 'week_15' }] : [],
        { title: 'PR', data: 'Returns Punts' },
        { title: 'KR', data: 'Returns Kickoffs',  },
        { title: 'sleeperADP', data: 'sleeperADP' },
        { title: 'yahooADP', data: 'yahooADP' },
        { title: 'fpros_pass_td', data: 'fpros_pass_td' },
        { title: 'fpros_int', data: 'fpros_int' },
      ];

      // Add all desired columns that aren't in the list above
      let hidden_cols = ['drafted', 'plain_name', 'Abbreviation']
      for (let i = 0; i < all_keys.length; i++) {
        let existing_columns = columns.map(col => col.data);
        if (!existing_columns.includes(all_keys[i]) && !hidden_cols.includes(all_keys[i]))
          columns.push({ title: all_keys[i], data: all_keys[i] });
      }

      // Move the Total Points column to the end
      columns.push(columns.splice(columns.findIndex((col) => col.title === 'Total Points'), 1)[0]);
      // Set the name equal to the title
      columns.forEach((col) => {
        col.name = col.title;
      });
      let numCols = columns.length;
      // console.log(columns);

      this.table = $(this.tableRef.current).DataTable({
        data: this.state.players,
        columns: columns,
        colReorder: true,
        fixedColumns: {
          start: 1,
          end: 1
        },
        autoWidth: true,
        columnDefs: [
          {
            orderSequence: [ 'desc', 'asc' ],
            targets: '_all'
          }
        ],
        rowCallback: (row, data) => {
          $(row).off('click').on('click', () => this.draft(data, row));
        },
        pageLength: 100,
        scrollY: '68vh',
        scrollCollapse: true,
        layout: {
          topStart: null,
          topEnd: 'search',
          bottomStart: ['info', 'pageLength'],
          bottomEnd: ['paging'],
        },
        order: [numCols - 1, 'desc'],
      });
      // Remove any players that have been drafted
      this.table.rows((i, data) => data.drafted).remove().draw();
      // this.table.order(['Total Points', 'desc']).draw();
    }

    fetchPlayers(format) {
      const self = this;

      let url;
      switch(format) {
        case 'dk_best_ball':
          url = 'overall_dk.json';
          break;
        case 'underdog_best_ball':
          url = 'overall_underdog.json';
          break;
        default:
          url = 'overall.json';
          break;
      }

      this.setState({ isLoading: true });
      fetch(url, {
        method: 'get'
      }).then((response) => {
        response.json().then(function(res){
          // Get the unique positions
          let positions = [];
          for (let p of res) {
            if (!positions.includes(p['Position']))
              positions.push(p['Position']);
          }

          // Add drafted attribute to every player object
          res.forEach(obj => { obj.drafted = null });

          self.setState({
            players: res,
            filteredPlayers: res,
            positions: ['All'].concat(positions),
            isLoading: false,
            format: format,
            query: '',
          });
          const table = $(self.tableRef.current).DataTable();
          if (table instanceof $.fn.dataTable.Api) {
            table.destroy();
            $(self.tableRef.current).empty();
          }
          self.initDataTable();
        });
      }).catch(function(err) {
        self.setState({
          fetchError: err,
          isLoading: false,
        });
      });
    }

    searchPlayers(query) {
      let players = this.state.players.filter(player =>
        player.name.toUpperCase().includes(query.toUpperCase())
      );

      this.setState({
        filteredPlayers: players,
        query: query,
      });
    }

    draft(player, row) {
      const players = this.state.players.slice();
      const index = players.indexOf(player);
      if (~index) {
          players[index].drafted = this.state.currentDraftPick + 1;
      }

      this.setState({
          currentDraftPick: this.state.currentDraftPick + 1,
          players: players,
          filteredPlayers: players,
          query: '',
      });

      const table = $(this.tableRef.current).DataTable();
      table.rows((i, data) => data.Position == player.Position).invalidate();
      table.row(row).remove().draw(false); // draw(false) keeps current sorting/paging
      if (table.search() != '')
        table.search('').draw()
    }

    undo(currentDraftPick) {
      if(currentDraftPick === 0)
        return;

      const players = this.state.players.slice();
      const index = players.findIndex(p => p.drafted === currentDraftPick);
      if (~index) {
          players[index].drafted = null;
      }

      this.setState({
          currentDraftPick: this.state.currentDraftPick - 1,
          players: players,
      },
      () => {
        // Add the player back to the DataTable
        const table = $(this.tableRef.current).DataTable();

        // Find the player that was just undone
        const player = players[index]

        if (player) {
          // Add the row back to the DataTable
          const rowNode = table.row.add(player).draw(false).node();
          $(rowNode).off('click').on('click', () => this.draft(player, rowNode));

          // Trigger recalculation of nextN columns
          table.rows((i, data) => data.Position == player.Position).invalidate();

          if (this.state.currentDraftPick === 0)
            localStorage.removeItem('draftBoardState');
        }
      });
    }

    reset() {
      const players = this.state.players.slice();
      players.map((player, i) => {
          return player.drafted = null;
      });

      this.setState({
          currentDraftPick: 0,
          players: players,
      },
      () => {
        const table = $(this.tableRef.current).DataTable();

        // Bulk update
        table.clear();
        table.rows.add(players);  // add all rows in one batch
        table.draw(false);

        // Re-attach row click handlers to all rows at once
        table.rows().every(function(index, tableLoop, rowLoop) {
          const rowData = table.row(index).data();
          const rowNode = table.row(index).node();
          $(rowNode).off('click').on('click', () => this.draft(rowData, rowNode));
        }.bind(this));
        table.rows().invalidate();

        localStorage.removeItem('draftBoardState');
      });
    }

    render() {
      if (this.state.isLoading) {
        return (<div className='row'>Loading...</div>)
      }

      if (this.state.fetchError) {
        return (<div className='row'>error fetching rankings...</div>)
      }


      return (
        <div style={{ width: '100%', margin: '0 auto' }} className='d-flex flex-column vh-100'>
          <div className='d-flex flex-row justify-content-between flex-nowrap mb-3'>
            <span className="flex-shrink-0 ms-3">
              <select value={ this.state.format } onChange={(e) => this.setState({format: e.target.value, currentDraftPick: 0}, () => this.fetchPlayers(this.state.format)) } >
                <option value="bn_league">BN League</option>
                <option value="underdog_best_ball">Underdog Best Ball (.5PPR)</option>
                <option value="dk_best_ball">DK Best Ball (1PPR)</option>
              </select>
            </span>
            <span className='d-flex flex-row flex-shrink-0'>
              {this.state.positions?.map((position, i) => (
                <button
                  key={i}
                  onClick={() => {
                    if (position === 'All') {
                      this.setState({ selectedPositions: ['All'] });
                      this.table.column('Position:name').search('').draw();
                      return;
                    }

                    // Copy current selected positions
                    let selectedPositions = [...this.state.selectedPositions];

                    if (selectedPositions.includes(position)) {
                      // Toggle off
                      selectedPositions = selectedPositions.filter(p => p !== position);
                    } else {
                      // Toggle on
                      selectedPositions = selectedPositions.filter(p => p !== 'All'); // remove 'All' if present
                      selectedPositions.push(position);
                    }

                    // Default back to 'All' if no positions are selected
                    if (selectedPositions.length === 0) selectedPositions = ['All'];

                    this.setState({ selectedPositions });

                    // Update DataTable search
                    this.table.column('Position:name').search(
                      selectedPositions.length === 1 && selectedPositions[0] === 'All'
                        ? ''
                        : (cellData) => selectedPositions.includes(cellData)
                    ).draw();
                  }}
                  style={{
                    fontWeight: this.state.selectedPositions.includes(position) ? 'bold' : 'normal',
                    backgroundColor: this.state.selectedPositions.includes(position) ? 'green' : 'white',
                    color: this.state.selectedPositions.includes(position) ? 'white' : 'black',
                    marginRight: '0.5rem',
                    borderRadius: '5px',
                    ...(position === 'All' ? { marginRight: '15px', marginLeft: '15px' } : {}),
                  }}
                >
                  {position}
                </button>
              ))}
            </span>
            <span className='flex-shrink-0 ms-3' style={{marginLeft: '30px'}}>
              <button
                key='rookieToggle'
                onClick={() => { 
                  let newState = !this.state.filterByRookie;
                  this.setState({ filterByRookie: newState });
                  this.table.column('Rookie:name').search(newState ? '✅' : '').draw();
                }}
                style={{
                  fontWeight: this.state.filterByRookie ? 'bold' : 'normal',
                  backgroundColor: this.state.filterByRookie ? 'orange' : 'white',
                  color: this.state.filterByRookie ? 'white' : 'black',
                  marginRight: '0.5rem',
                  borderRadius: '5px'
                }}
              >
                Rookies
              </button>
            </span>
          </div>

          <div className='col-md-10 flex-grow-1'>
            <table
              className='table table-striped table-hover display'
              // pagination
              // highlightOnHover
              ref={this.tableRef}
            >
              {/* <thead>
                <tr>
                  <th>Player</th>
                  <th>Position</th>
                  <th>Team</th>
                  <th>Age</th>
                  <th>Total Points</th>
                  <th>Pass Yards</th>
                  <th>Pass TDs</th>
                  <th>Rush Yards</th>
                  <th>Rush TDs</th>
                </tr>
              </thead>
              <tbody>
                {this.state.players.slice().filter(p => !p.drafted).map(player => (
                  <tr key={player.Player}
                    onClick={() => this.draft(player, row)}
                  >
                    <td>{player.Player}</td>
                    <td>{player.Position}</td>
                    <td>{player.team_abbrev}</td>
                    <td>{player.age}</td>
                    <td>{player['Total Points'] ?? 0}</td>
                    <td>{player['fpros.pass_yd'] ?? 0}</td>
                    <td>{player['fpros.pass_td'] ?? 0}</td>
                    <td>{player['fpros.rush_yd'] ?? 0}</td>
                    <td>{player['fpros.rush_td'] ?? 0}</td>
                  </tr>
                ))}
              </tbody> */}
            </table>
          </div>

          <Drafted2
              currentDraft={ this.state.currentDraftPick }
              players={ this.state.players }
              undo={ (c) => this.undo(c) }
              reset={ () => this.reset() }
          />
        </div>
      );
    }
}

export default DraftBoard;
